      options.content = args[++i];
    } else if (args[i] === '--output' && i + 1 < args.length) {
      options.output = args[++i];
    } else if (args[i] === '--templates' && i + 1 < args.length) {
      options.templates = args[++i];
    }
  }
  return options;
}

function parseServeArgs(args: string[]): ServeOptions {
